type CartLine = { sku: string; quantity: number };

function parseCart(raw: unknown): CartLine[] {
  if (!Array.isArray(raw)) {
    return [];
  }
  const lines: CartLine[] = [];
  for (const item of raw) {
    if (typeof item !== "object" || item === null) {
      continue;
    }
    const record = item as Record<string, unknown>;
    if (typeof record.sku !== "string" || record.sku.length === 0) {
      continue;
    }
    if (typeof record.quantity !== "number" || !Number.isInteger(record.quantity)) {
      continue;
    }
    if (record.quantity <= 0) {
      continue;
    }
    lines.push({ sku: record.sku, quantity: record.quantity });
  }
  return lines;
}
